/// <summary>
/// Extension of formDataSource smmBusRelTable of Form SalesQuotationListPage
/// </summary>
[ExtensionOf(formDataSourceStr(SalesQuotationListPage, smmBusRelTable))]
final class AVASalesQuotationListPageFrm_smmBusRelTable_Extension
{
}

Method.Source:
/// <summary>
/// Extension of init method
/// </summary>
public void init()
{
    next init();

    FormDataSource avaSmmBusRelTable_fds = this;
    FormRun avaFormRun = avaSmmBusRelTable_fds.formRun();
    Args avaArgs = avaFormRun.args();

    if(avaArgs.callerName() == formStr(smmBusRelTable)
        && avaArgs.dataset() == tableNum(smmBusRelTable))
    {
        smmBusRelTable          avaBusRelTable = avaArgs.record() as smmBusRelTable;
        QueryBuildRange         accountRange;

        avaSmmBusRelTable_fds.query().dataSourceTable(tableNum(SalesQuotationTable)).clearDynalinks();

        accountRange = SysQuery::findOrCreateRange(avaSmmBusRelTable_fds.query().dataSourceTable(tableNum(SalesQuotationTable)),fieldNum(SalesQuotationTable, BusRelAccount));
        accountRange.value(strFmt('(((%1.%2) like "%3") || ((%1.%4) like "%3")))',
                                avaFormRun.dataSource('SalesQuotationTable').name(),
                                fieldStr(SalesQuotationTable, CustAccount),
                                avaBusRelTable.BusRelAccount,
                                fieldStr(SalesQuotationTable, BusRelAccount)));
    }
}
